<script setup>import {onMounted,ref,computed} from 'vue';import Button from 'primevue/button';import Card from 'primevue/card';import StatCard from '../../components/StatCard.vue';import {rpc} from '../../services/supabase';const attendance=ref({sessions:[],active:null}),grades=ref([]),schedules=ref([]),loading=ref(true);const students=computed(()=>{const x=new Set();attendance.value.active?.records?.forEach(v=>x.add(v.studentCode));grades.value.forEach(g=>g.grades?.forEach(v=>x.add(v.studentCode)));return x.size});onMounted(async()=>{try{[attendance.value,grades.value,schedules.value]=await Promise.all([rpc('teacher_attendance_dashboard'),rpc('teacher_gradebook_get'),rpc('teacher_schedule_get')])}finally{loading.value=false}})</script>
<template><div class="welcome"><h1>สวัสดีครับ ครูผู้สอน</h1><p>ยินดีต้อนรับสู่ Education Hub</p></div><div class="stats"><StatCard icon="pi-users" label="นักเรียนทั้งหมด" :value="students" unit="คน" tone="blue"/><StatCard icon="pi-check-circle" label="รอบเช็คชื่อทั้งหมด" :value="attendance.sessions?.length||0" unit="รอบ" tone="green"/><StatCard icon="pi-star" label="รายการคะแนน" :value="grades.length" unit="รายการ" tone="orange"/><StatCard icon="pi-calendar" label="ตารางเรียน" :value="schedules.length" unit="รายการ" tone="purple"/></div><div class="dashboardGrid"><Card><template #title>รอบเช็คชื่อปัจจุบัน</template><template #content><div v-if="attendance.active" class="activeCode"><small>รหัสเช็คชื่อ</small><strong>{{attendance.active.code}}</strong><b>{{attendance.active.title}}</b><RouterLink to="/teacher/attendance"><Button label="ดูรายละเอียด"/></RouterLink></div><div v-else class="empty"><i class="pi pi-plus-circle"/><b>สร้างรหัสเช็คชื่อ</b><small>เพื่อเริ่มรอบเช็คชื่อใหม่</small><RouterLink to="/teacher/attendance"><Button label="สร้างรหัสเช็คชื่อ"/></RouterLink></div></template></Card><Card><template #title>เมนูลัด</template><template #content><div class="quick"><RouterLink to="/teacher/attendance"><i class="pi pi-play green"/>สร้างรหัสเช็คชื่อ</RouterLink><RouterLink to="/teacher/students"><i class="pi pi-users blue"/>ดูรายชื่อนักเรียน</RouterLink><RouterLink to="/teacher/grades"><i class="pi pi-star orange"/>จัดการคะแนน</RouterLink><RouterLink to="/teacher/schedule"><i class="pi pi-calendar purple"/>จัดการตารางเรียน</RouterLink></div></template></Card></div></template>
